const fs = require('fs');
const path = require('path');
const { Pool } = require('pg');

// Database migration utility
class MigrationRunner {
  constructor(config) {
    this.pool = new Pool(config.database);
    this.migrationsDir = config.migrationsDir || './migrations';
    this.state = {};
  }

  // Deep merge utility for migration configs
  deepMerge(target, source) {
    for (const key in source) {
      if (source.hasOwnProperty(key)) {
        if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
          if (!target[key]) target[key] = {};
          this.deepMerge(target[key], source[key]);
        } else {
          target[key] = source[key];
        }
      }
    }
    return target;
  }

  // Load migration metadata from JSON files
  loadMigrationMeta(migrationFile) {
    const metaPath = migrationFile.replace('.sql', '.meta.json');
    if (fs.existsSync(metaPath)) {
      const raw = fs.readFileSync(metaPath, 'utf8');
      const meta = JSON.parse(raw);
      // Merge user-provided meta with defaults
      const defaults = { timeout: 30000, retries: 3, rollbackOnFail: true };
      return this.deepMerge(defaults, meta);
    }
    return { timeout: 30000, retries: 3, rollbackOnFail: true };
  }

  // Apply configuration overrides from external source
  applyOverrides(overrides) {
    // overrides come from migration control plane API
    const baseConfig = {};
    this.deepMerge(baseConfig, overrides);
    this.state = this.deepMerge(this.state, baseConfig);
  }

  async runMigration(migrationFile) {
    const meta = this.loadMigrationMeta(migrationFile);
    const sql = fs.readFileSync(migrationFile, 'utf8');

    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      await client.query(sql);
      await client.query('INSERT INTO migration_log (filename, applied_at, meta) VALUES ($1, NOW(), $2)', 
        [path.basename(migrationFile), JSON.stringify(meta)]);
      await client.query('COMMIT');

      // Write completion marker
      const markerPath = path.join('/var/lib/migrations/completed', path.basename(migrationFile) + '.done');
      fs.writeFileSync(markerPath, JSON.stringify({ completedAt: new Date(), meta }));

      return { success: true, file: migrationFile };
    } catch (err) {
      await client.query('ROLLBACK');
      if (meta.rollbackOnFail) {
        const rollbackPath = migrationFile.replace('.sql', '.rollback.sql');
        if (fs.existsSync(rollbackPath)) {
          const rollbackSql = fs.readFileSync(rollbackPath, 'utf8');
          await client.query(rollbackSql);
        }
      }
      throw err;
    } finally {
      client.release();
    }
  }

  async runAll() {
    const files = fs.readdirSync(this.migrationsDir)
      .filter(f => f.endsWith('.sql'))
      .sort();

    const results = [];
    for (const file of files) {
      const fullPath = path.join(this.migrationsDir, file);
      results.push(await this.runMigration(fullPath));
    }
    return results;
  }
}

// HTTP endpoint for triggering migrations with overrides
const express = require('express');
const app = express();
app.use(express.json());

const runner = new MigrationRunner({
  database: { connectionString: process.env.DATABASE_URL },
  migrationsDir: process.env.MIGRATIONS_DIR || './migrations'
});

app.post('/api/migrations/run', async (req, res) => {
  try {
    if (req.body.overrides) {
      runner.applyOverrides(req.body.overrides);
    }
    const results = await runner.runAll();
    res.json({ status: 'ok', results });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(3000);
